-- Remaining source PostgreSQL uniqueness/validation rules translated to SQLite.
CREATE UNIQUE INDEX custom_tags_name_unique ON custom_tags(user_id,name);
CREATE UNIQUE INDEX ai_keys_name_unique ON user_ai_api_keys(user_id,provider,name);
CREATE UNIQUE INDEX external_service_unique ON user_external_tokens(user_id,service);
CREATE TRIGGER blocks_validate_0_insert BEFORE INSERT ON blocks WHEN julianday(NEW.occurred_at) IS NULL OR julianday(NEW.occurred_at)>julianday('now','+5 minutes') BEGIN SELECT RAISE(ABORT,'Invalid or future occurred_at'); END;
CREATE TRIGGER blocks_validate_0_update BEFORE UPDATE ON blocks WHEN julianday(NEW.occurred_at) IS NULL OR julianday(NEW.occurred_at)>julianday('now','+5 minutes') BEGIN SELECT RAISE(ABORT,'Invalid or future occurred_at'); END;
CREATE TRIGGER blocks_validate_1_insert BEFORE INSERT ON blocks WHEN NEW.category='schedule' AND (NEW.starts_at IS NULL OR julianday(NEW.starts_at) IS NULL OR (NEW.ends_at IS NOT NULL AND (julianday(NEW.ends_at) IS NULL OR julianday(NEW.ends_at)<julianday(NEW.starts_at)))) BEGIN SELECT RAISE(ABORT,'Invalid schedule times'); END;
CREATE TRIGGER blocks_validate_1_update BEFORE UPDATE ON blocks WHEN NEW.category='schedule' AND (NEW.starts_at IS NULL OR julianday(NEW.starts_at) IS NULL OR (NEW.ends_at IS NOT NULL AND (julianday(NEW.ends_at) IS NULL OR julianday(NEW.ends_at)<julianday(NEW.starts_at)))) BEGIN SELECT RAISE(ABORT,'Invalid schedule times'); END;
CREATE TRIGGER blocks_validate_2_insert BEFORE INSERT ON blocks WHEN NEW.tag IS NOT NULL AND NEW.tag NOT IN ('work','family','private') AND NOT(length(NEW.tag)=36 AND substr(NEW.tag,9,1)='-' AND substr(NEW.tag,14,1)='-' AND substr(NEW.tag,19,1)='-' AND substr(NEW.tag,24,1)='-' AND length(replace(NEW.tag,'-',''))=32 AND replace(NEW.tag,'-','') NOT GLOB '*[^0-9a-f]*') BEGIN SELECT RAISE(ABORT,'Invalid tag'); END;
CREATE TRIGGER blocks_validate_2_update BEFORE UPDATE ON blocks WHEN NEW.tag IS NOT NULL AND NEW.tag NOT IN ('work','family','private') AND NOT(length(NEW.tag)=36 AND substr(NEW.tag,9,1)='-' AND substr(NEW.tag,14,1)='-' AND substr(NEW.tag,19,1)='-' AND substr(NEW.tag,24,1)='-' AND length(replace(NEW.tag,'-',''))=32 AND replace(NEW.tag,'-','') NOT GLOB '*[^0-9a-f]*') BEGIN SELECT RAISE(ABORT,'Invalid tag'); END;
CREATE TRIGGER user_ai_settings_validate_0_insert BEFORE INSERT ON user_ai_settings WHEN typeof(NEW.day_boundary_hour)<>'integer' OR NEW.day_boundary_hour<0 OR NEW.day_boundary_hour>12 BEGIN SELECT RAISE(ABORT,'Invalid day boundary'); END;
CREATE TRIGGER user_ai_settings_validate_0_update BEFORE UPDATE ON user_ai_settings WHEN typeof(NEW.day_boundary_hour)<>'integer' OR NEW.day_boundary_hour<0 OR NEW.day_boundary_hour>12 BEGIN SELECT RAISE(ABORT,'Invalid day boundary'); END;
CREATE TRIGGER user_ai_models_validate_0_insert BEFORE INSERT ON user_ai_models WHEN NEW.provider NOT IN ('openai','anthropic','google') BEGIN SELECT RAISE(ABORT,'Invalid AI provider'); END;
CREATE TRIGGER user_ai_models_validate_0_update BEFORE UPDATE ON user_ai_models WHEN NEW.provider NOT IN ('openai','anthropic','google') BEGIN SELECT RAISE(ABORT,'Invalid AI provider'); END;
CREATE TRIGGER user_image_storage_settings_validate_0_insert BEFORE INSERT ON user_image_storage_settings WHEN NEW.provider NOT IN ('default','gyazo') BEGIN SELECT RAISE(ABORT,'Invalid image provider'); END;
CREATE TRIGGER user_image_storage_settings_validate_0_update BEFORE UPDATE ON user_image_storage_settings WHEN NEW.provider NOT IN ('default','gyazo') BEGIN SELECT RAISE(ABORT,'Invalid image provider'); END;
